	const path = row.path;
	if (!path) return { redirect: kind === "thumbnail" ? `/wallpapers/thumbs/${row.id}.webp` : `/wallpapers/${row.id}.jpg` };
	if (path.startsWith("/wallpapers/")) return { redirect: kind === "thumbnail" ? `/wallpapers/thumbs/${row.id}.webp` : `/wallpapers/${row.id}.jpg` };
